function patchExecutor(s){const a="  imotion_marketing_targets_register_v2:{operation:'host_action.imotion_marketing_targets_register_v2',kind:'imotion_marketing_targets_register_v2'},\n  drtarjomeh_security_containment_v1:";const b="  imotion_marketing_targets_register_v2:{operation:'host_action.imotion_marketing_targets_register_v2',kind:'imotion_marketing_targets_register_v2'},\n  control_plane_typed_bootstrap_transport_v1:{operation:'host_action.control_plane_typed_bootstrap_transport_v1',kind:'control_plane_typed_bootstrap_transport_v1'},\n  drtarjomeh_security_containment_v1:";s=replaceOnce(s,a,b,'executor_registry');const anchor="const applyHostActionV2Original=applyHostActionV2;\n";const runner=`const CONTROL_PLANE_TYPED_BOOTSTRAP_HELPER='${PATHS.helper}';\nconst CONTROL_PLANE_TYPED_BOOTSTRAP_RESULT='/var/lib/prhm-agent-selfmaint-exec/control-plane-typed-bootstrap-transport-v1/latest.json';\nfunction applyControlPlaneTypedBootstrapTransportV1(){if(!fs.existsSync(CONTROL_PLANE_TYPED_BOOTSTRAP_HELPER))throw new Error('typed_bootstrap_helper_missing');fs.mkdirSync('/opt/prhm-deployhq-control',{recursive:true,mode:0o755});fs.mkdirSync('/var/lib/prhm-agent-selfmaint-exec/control-plane-typed-bootstrap-transport-v1',{recursive:true,mode:0o700});try{if(fs.existsSync(CONTROL_PLANE_TYPED_BOOTSTRAP_RESULT))fs.unlinkSync(CONTROL_PLANE_TYPED_BOOTSTRAP_RESULT)}catch{};const u='prhm-control-plane-typed-bootstrap-transport-v1-'+Date.now();const a=['--wait','--unit='+u,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=strict','--property=ProtectHome=read-only','--property=ReadWritePaths=/opt/prhm-deployhq-control /opt/prhm-agent-selfmaint-exec/actions /var/lib/prhm-agent-selfmaint-exec /etc/systemd/system','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',CONTROL_PLANE_TYPED_BOOTSTRAP_HELPER,'--apply'];cp.execFileSync('/usr/bin/systemd-run',a,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:600000});const r=readJson(CONTROL_PLANE_TYPED_BOOTSTRAP_RESULT);const p=r&&r.preflight;if(r.ok!==true||r.action!=='control_plane_typed_bootstrap_transport_v1'||r.schema_version!=='prhm.bootstrap-result.v1'||r.package_id!=='deployhq_control_adapter_node1_recreate_v1'||r.installed!==true||r.deployhq_mutation!==false||r.application_mutation!==false||r.honartik_mutation!==false||r.imotion_mutation!==false||r.rollback_failed!==false||!p||p.source_commit_match!==true||p.manifest_sha_match!==true||p.all_file_sha_match!==true||p.destination_allowlist_pass!==true||p.symlink_guard_pass!==true||p.syntax_pass!==true||p.baseline_match!==true)throw new Error('typed_bootstrap_result_invalid');return r}\n`;s=replaceOnce(s,anchor,runner+anchor,'executor_runner');const d="if(action==='imotion_marketing_targets_register_v2')return applyImotionMarketingTargetsRegisterV2();";const dn="if(action==='control_plane_typed_bootstrap_transport_v1')return applyControlPlaneTypedBootstrapTransportV1();if(action==='imotion_marketing_targets_register_v2')return applyImotionMarketingTargetsRegisterV2();";return replaceOnce(s,d,dn,'executor_dispatch')}
function patchPolicy(s){const d=JSON.parse(s);if(!d.operations||!Array.isArray(d.typed_scopes))fail('policy_shape_invalid');if(d.operations[OPERATION]||d.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_target_already_exists');d.operations[OPERATION]={level:4};d.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});return JSON.stringify(d,null,2)+'\n'}
function patchMcp(s){const a="'imotion_marketing_targets_register_v2','drtarjomeh_security_containment_v1'";const b="'imotion_marketing_targets_register_v2','control_plane_typed_bootstrap_transport_v1','drtarjomeh_security_containment_v1'";return replaceOnce(s,a,b,'mcp_enum')}
function patchZdt(s,h){s=replaceOnce(s,ZDT_OLD.mcp,h.mcp,'zdt_mcp');s=replaceOnce(s,ZDT_OLD.base,h.base,'zdt_base');s=replaceOnce(s,ZDT_OLD.executor,h.executor,'zdt_executor');return s}
function helperForPostRegistration(h){const b=Buffer.from(HELPER_TEMPLATE_B64,'base64');if(sha(b)!==HELPER_TEMPLATE_SHA)fail('helper_template_sha_mismatch');const old=`const PRE_REGISTRATION_BASELINE=Object.freeze({"base":"f948c66f71f0e25d08f9bc29ac829cba4351f2f7bfba0ae56d81aba607114602","executor":"45c4e8a96b8cc6d88939a4af582b7c1aefbbb2dc3217b67b5317d0950df94c36","policy":"27be60fd0b43bf02578bc5afa680f22ce51954c3e63c9a8514eb5cca17aee35d","mcp":"a2f8ff5110a071420f555102201e371fbf3cf2bded31353ddf51ee1848553e16","zdt":"966d91c5af901f2f96e782c1f83915a49b9831f9b226000944a65e25b56e009b"});`;const post='const PRE_REGISTRATION_BASELINE=Object.freeze('+JSON.stringify({base:h.base,executor:h.executor,policy:h.policy,mcp:h.mcp,zdt:h.zdt})+');';const text=b.toString('utf8');return Buffer.from(replaceOnce(text,old,post,'helper_post_baseline'),'utf8')}
