function build(){verifyBaseline();const base=Buffer.from(patchBase(fs.readFileSync(PATHS.base,'utf8'))),executor=Buffer.from(patchExecutor(fs.readFileSync(PATHS.executor,'utf8'))),policy=Buffer.from(patchPolicy(fs.readFileSync(PATHS.policy,'utf8'))),mcp=Buffer.from(patchMcp(fs.readFileSync(PATHS.mcp,'utf8')));const h={base:sha(base),executor:sha(executor),policy:sha(policy),mcp:sha(mcp)};const zdt=Buffer.from(patchZdt(fs.readFileSync(PATHS.zdt,'utf8'),h));h.zdt=sha(zdt);const helper=helperForPostRegistration(h);h.helper=sha(helper);syntax(base);syntax(executor);syntax(mcp,true);syntax(zdt);syntax(helper);JSON.parse(policy.toString('utf8'));return {base,executor,policy,mcp,zdt,helper,hashes:h}}
function atomic(f,b,mode){fs.mkdirSync(path.dirname(f),{recursive:true,mode:0o755});const t=f+'.typed-bootstrap-'+process.pid+'.tmp';fs.writeFileSync(t,b,{mode,flag:'wx'});fs.renameSync(t,f);fs.chmodSync(f,mode)}
function backupOriginals(){const dir=path.join(BACKUP_ROOT,new Date().toISOString().replace(/[:.]/g,'-'));fs.mkdirSync(dir,{recursive:true,mode:0o700});const states={};for(const k of ['base','executor','policy','mcp','zdt']){const st=fs.statSync(PATHS[k]),bak=path.join(dir,k+'.bak');fs.copyFileSync(PATHS[k],bak,fs.constants.COPYFILE_EXCL);fs.chmodSync(bak,0o600);states[k]={backup:bak,mode:st.mode&0o777,sha256:shaFile(PATHS[k])}}return {dir,states}}
function restoreBackup(b,mutated){for(const k of [...mutated].reverse()){if(k==='helper'){try{fs.unlinkSync(PATHS.helper)}catch(e){if(e.code!=='ENOENT')throw e};continue}const st=b.states[k],bytes=fs.readFileSync(st.backup);if(sha(bytes)!==st.sha256)fail('backup_sha_mismatch:'+k);atomic(PATHS[k],bytes,st.mode)}}
function restartServices(){for(const u of ['prhm-company-approval.service','prhm-agent-selfmaint.service','prhm-agent-selfmaint-exec.service']){cp.execFileSync('/usr/bin/systemctl',['restart',u],{encoding:'utf8',timeout:90000});const r=cp.execFileSync('/usr/bin/systemctl',['is-active',u],{encoding:'utf8',timeout:30000}).trim();if(r!=='active')fail('service_not_active:'+u)}}
function resultBase(){return {ok:false,action:INSTALLER_ACTION,target_action:ACTION,package_id:PACKAGE_ID,schema_version:'prhm.host-action-bootstrap-result.v1',production_mutation:false,deployhq_mutation:false,application_mutation:false,honartik_mutation:false,imotion_mutation:false,mcp_refresh_required:true,rollback_performed:false,rollback_failed:false}}
function preflight(){const c=build();return {...resultBase(),ok:true,preflight_only:true,production_mutation:false,baseline_match:true,candidate_sha256:c.hashes,helper_template_sha256:HELPER_TEMPLATE_SHA}}
function apply(){const out=resultBase(),c=build(),b=backupOriginals(),mut=[];try{for(const k of ['helper','base','executor','policy','mcp','zdt']){mut.push(k);atomic(PATHS[k],c[k],k==='helper'?0o750:b.states[k].mode);if(shaFile(PATHS[k])!==c.hashes[k])fail('post_write_sha_mismatch:'+k)}restartServices();Object.assign(out,{ok:true,installed:true,preflight_only:false,production_mutation:true,post_install_sha256:c.hashes,backup_dir:b.dir});atomic(RESULT,Buffer.from(JSON.stringify(out,null,2)+'\n'),0o600);return out}catch(e){try{restoreBackup(b,mut);restartServices();out.rollback_performed=true}catch(rb){out.rollback_failed=true;throw new Error('install_failed_and_rollback_failed:'+e.message+':'+rb.message)}throw new Error('install_failed_rolled_back:'+e.message)}}
